mapper.sql:
WHERE tenant_id = #{tenantId}
  AND workspace_id = #{workspaceId}
  AND deleted_at IS NULL

  AND raw_prompt ILIKE '%' || #{keyword} || '%' ESCAPE E'\\'


  AND created_at >= #{createdFrom}
  AND created_at < #{createdToExclusive}

mapper.select:
SELECT 
  FROM optimization_record
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND workspace_id = #{workspaceId}
   AND deleted_at IS NULL

mapper.update:
UPDATE optimization_record
   SET deleted_at = #{deletedAt}
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND workspace_id = #{workspaceId}
   AND deleted_at IS NULL
